async (page) => { await page.setViewportSize({width:1216,height:1040}); await page.setContent("<!doctype html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <link rel=\"icon\" href=\"data:,\">\n  <title>Preview Perbaikan Sidebar Phoenix</title>\n  <style>\n    * {box-sizing: border-box}\n    body {margin: 0; background: #f3f5f5; color: #202824; font-family: 'Segoe UI', sans-serif}\n    main {max-width: 1216px; margin: auto; padding: 32px 40px 24px}\n    header {display: flex; align-items: start; justify-content: space-between; gap: 24px; margin-bottom: 24px}\n    h1 {font-size: 26px; line-height: 1.2; font-weight: 650; margin: 0 0 8px; letter-spacing: -.5px}\n    header p {font-size: 14px; margin: 0; color: #5d6761; line-height: 1.5}\n    .status {margin-top: 4px; border: 1px solid #cddfd5; border-radius: 6px; background: #eaf4ef; color: #246548; padding: 8px 12px; font-size: 12px; white-space: nowrap}\n    .states {display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 28px}\n    figure {margin: 0; background: white; border: 1px solid #dce1de; border-radius: 12px; overflow: hidden}\n    figcaption {padding: 16px 17px; min-height: 80px; border-bottom: 1px solid #e4e8e5}\n    h2 {margin: 0 0 5px; font-size: 15px; font-weight: 650}\n    figcaption p {margin: 0; font-size: 12px; color: #606963; line-height: 1.5}\n    figure a {display: block; line-height: 0}\n    img {display: block; width: 100%; height: auto}\n    footer {font-size: 12px; color: #59645d; margin-top: 18px; line-height: 1.5}\n    a:focus-visible {outline: 3px solid #1fa675; outline-offset: -3px}\n    @media(max-width: 900px) {.states {grid-template-columns: 1fr} main{max-width: 440px;padding: 24px} header{display: block} .status{display: inline-block;margin-top: 16px}}\n  </style>\n</head>\n<body>\n<main>\n  <header>\n    <div><h1>Preview revisi posisi hover</h1><p>Badan panel tepat di batas sidebar, dengan panah ke kiri sesuai referensi Anda.</p></div>\n    <div class=\"status\">Preview saja • Belum diterapkan</div>\n  </header>\n  <div class=\"states\">\n    <figure>\n      <figcaption><h2>01 · Sidebar terbuka</h2><p>Nama kategori tampil; submenu diberi indentasi.</p></figcaption>\n      <a href=\"01-expanded.png\" aria-label=\"Buka gambar lengkap sidebar terbuka\"><img src=\"data:image/png;base64,\" width=\"360\" height=\"800\" alt=\"Sidebar terbuka menampilkan kategori All Menus dan submenu Testing.\"></a>\n    </figure>\n    <figure>\n      <figcaption><h2>02 · Hover menu</h2><p>Badan panel sejajar sidebar; panah menjorok ke kiri.</p></figcaption>\n      <a href=\"02-collapsed-tooltip.png\" aria-label=\"Buka gambar lengkap sidebar hanya ikon\"><img src=\"data:image/png;base64,\" width=\"360\" height=\"800\" alt=\"Tooltip Manage Articles mulai di batas kanan sidebar, dengan panah penunjuk ke kiri.\"></a>\n    </figure>\n    <figure>\n      <figcaption><h2>03 · Hover submenu</h2><p>Posisi panel dan panah mengikuti pola yang sama.</p></figcaption>\n      <a href=\"03-collapsed-submenu.png\" aria-label=\"Buka gambar lengkap hover submenu\"><img src=\"data:image/png;base64,\" width=\"360\" height=\"800\" alt=\"Panel submenu Testing selebar 240 piksel, dengan ikon dan teks yang memiliki jarak rapi.\"></a>\n    </figure>\n  </div>\n  <footer>Nama kategori mengikuti data menu yang dibuat. Saat ini kategori aktif: <strong>All Menus</strong>. Klik gambar untuk melihat tampilan halaman lengkap.</footer>\n</main>\n</body>\n</html>\n"); await page.screenshot({path:"D:/Laragon/www/laravel-13-phoenix/project-artifacts/sidebar-category-preview-20261113/preview-comparison.png",fullPage:true}); return {images:await page.locator("img").count(),title:await page.title()}; }
